### PricingCard.tsx
```tsx
import React, { useState } from "react";
import { CheckIcon } from "lucide-react";
import { plans } from "../mockData";

type Plan = {
  name: string;
  priceMonthly: number;
  priceYearly: number;
  features: string[];
  isYearly: boolean;
};

type PricingCardProps = {
  plan: Plan;
};

const PricingCard: React.FC<PricingCardProps> = ({ plan }) => {
  const [isYearly, setIsYearly] = useState(false);

  const togglePlan = () => {
    setIsYearly(!isYearly);
  };

  const currentPrice = isYearly ? plan.priceYearly : plan.priceMonthly;
  const formattedPrice = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(currentPrice);

  return (
    <div className="max-w-md w-full bg-white rounded-lg shadow-md overflow-hidden border border-gray-100">
      <div className="p-6">
        <h2 className="text-2xl font-semibold text-gray-800 mb-4">{plan.name}</h2>

        <div className="flex justify-between items-center mb-6">
          <div className="text-3xl font-bold text-gray-900">{formattedPrice}</div>
          <button
            onClick={togglePlan}
            className="text-sm text-accent font-medium hover:underline transition-colors"
          >
            {isYearly ? "Monthly" : "Yearly"}
          </button>
        </div>

        <ul className="space-y-3 mb-6">
          {plan.features.map((feature, index) => (
            <li key={index} className="flex items-center gap-2">
              <CheckIcon className="w-4 h-4 text-accent" />
              <span className="text-gray-700">{feature}</span>
            </li>
          ))}
        </ul>

        <button className="w-full bg-accent text-white py-3 rounded-md font-medium hover:bg-blue-600 transition-colors">
          Buy Now
        </button>
      </div>
    </div>
  );
};

export { PricingCard };
```
